# 1. Extract original vertices
original_vertices = sorted({
    vertex
    for facet in original_facets
    for vertex in facet
})

print("Original vertices:", original_vertices)

# 2. Find every vertex Sage created in the subdivision
subdivision_vertices = {
    vertex
    for edge in subdivision
    for vertex in edge
}

# 3. Anything with length > 1 represents a newly-created
# barycentric subdivision vertex
new_vertices = sorted(
    vertex
    for vertex in subdivision_vertices
    if len(vertex) > 1
)

# 4. Assign reserved midpoint labels and skip them when numbering the rest.
def normalize_reservations(faces, labels):
    """Accept a single flat face/scalar label or parallel lists of each."""
    if not isinstance(faces, (list, tuple)):
        raise ValueError("protected_faces must be a face such as [1, 2] or a list of faces")
    if faces and all(type(vertex) is int for vertex in faces):
        faces = [faces]
    if type(labels) is int:
        labels = [labels]
    if not isinstance(labels, (list, tuple)):
        raise ValueError("reserved_labels must be an integer or a list of integers")
    normalized_faces = []
    for face in faces:
        if (not isinstance(face, (list, tuple)) or len(face) < 2
                or any(type(vertex) is not int for vertex in face)):
            raise ValueError("Each protected face must contain at least two integer vertices")
        if len(set(face)) != len(face):
            raise ValueError(f"Repeated vertex in protected face: {face}")
        normalized_faces.append(tuple(sorted(face)))
    return normalized_faces, list(labels)


protected_faces, reserved_labels = normalize_reservations(protected_faces, reserved_labels)
protected_barycenters = [tuple(sorted(face)) for face in protected_faces]
if len(protected_barycenters) != len(reserved_labels):
    raise ValueError("Each protected face must have one reserved label")
if any(type(label) is not int for label in reserved_labels):
    raise ValueError("Reserved labels must be integers")
if len(set(reserved_labels)) != len(reserved_labels):
    raise ValueError("Reserved labels must be distinct")
if len(set(protected_barycenters)) != len(protected_barycenters):
    raise ValueError("Protected faces must be distinct")

# Include manually inserted vertices even if absent from original_facets.
existing_labels = set(original_vertices) | {
    vertex[0] for vertex in subdivision_vertices if len(vertex) == 1
}
collisions = set(reserved_labels) & existing_labels
if collisions:
    raise ValueError(f"Reserved labels already used by original vertices: {sorted(collisions)}")
missing = set(protected_barycenters) - set(new_vertices)
if missing:
    raise ValueError(f"Protected midpoint faces absent from subdivision: {sorted(missing)}")

new_vertex_mapping = dict(zip(protected_barycenters, reserved_labels))
used_labels = existing_labels | set(reserved_labels)
next_id = max(existing_labels, default=0) + 1
for vertex in new_vertices:
    if vertex in new_vertex_mapping:
        continue
    while next_id in used_labels:
        next_id += 1
    new_vertex_mapping[vertex] = next_id
    used_labels.add(next_id)
    next_id += 1

print("New vertex mapping:")
for vertex, new_id in new_vertex_mapping.items():
    print(f"{vertex} -> {new_id}")


# 5. Convert a Sage barycentric vertex into an integer
def convert_vertex(vertex):
    # Singleton tuple = original vertex
    if len(vertex) == 1:
        return vertex[0]

    # Multi-element tuple = new barycentric vertex
    return new_vertex_mapping[vertex]


# 6. Convert the entire subdivision
converted_subdivision = {
    tuple(convert_vertex(vertex) for vertex in edge)
    for edge in subdivision
}

output_path = (
    Path(__file__).resolve().parents[1]
    / "knots"
    / "sdB_20_120_relabeled.txt"
)
output_path.parent.mkdir(parents=True, exist_ok=True)

# Sort both the vertices and facets so the file is deterministic across
# runs. JSON's nested square-bracket syntax can also be read as a GAP list.
serialized_subdivision = sorted(
    sorted(facet)
    for facet in converted_subdivision
)

with output_path.open("w", encoding="utf-8") as output_file:
    json.dump(serialized_subdivision, output_file)
    output_file.write("\n")

print(f"Converted subdivision written to: {output_path}")
